const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const regionOfInterest = ee.Geometry.LineString([
        [-91.22, 33.02], // Near Vicksburg, MS
        [-91.08, 32.18],
        [-90.87, 31.33],
        [-90.15, 30.00]  // Near New Orleans, LA
    ]).buffer(10000); // Buffer the line by 10km to create a polygon

    const date1 = '2019-12-04';
    const date2 = '2020-02-02';

    // 2. Data Acquisition & Processing Function
    const getWaterExtent = function(date, geometry) {
        // Use Sentinel-1 SAR to avoid cloud issues. Water has low backscatter (dark).
        const collection = ee.ImageCollection('COPERNICUS/S1_GRD')
            .filterDate(date, ee.Date(date).advance(1, 'day'))
            .filterBounds(geometry)
            .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
            .filter(ee.Filter.eq('instrumentMode', 'IW'));

        const imageCount = collection.size().getInfo();
        if (imageCount === 0) {
            return { 'count': 0, 'image': null, 'water_area': null };
        }

        const image = collection.mosaic().clip(geometry);

        // Check for valid pixels in the source image
        const pixelCheck = image.reduceRegion({
            reducer: ee.Reducer.count(),
            geometry: geometry,
            scale: 1000,
            maxPixels: 1e9
        });

        if (pixelCheck.get('VV').getInfo() === null || pixelCheck.get('VV').getInfo() === 0) {
            return { 'count': imageCount, 'image': image, 'water_area': null, 'no_pixels': true };
        }

        // A common threshold for water in Sentinel-1 VV band is < -16 dB.
        const waterMask = image.select('VV').lt(-16);
        const waterImage = waterMask.updateMask(waterMask); // Mask so only water pixels are counted

        // Calculate the area of water pixels.
        const waterArea = waterImage.multiply(ee.Image.pixelArea()).reduceRegion({
            reducer: ee.Reducer.sum(),
            geometry: geometry,
            scale: 1000, // Use a coarse scale to avoid timeouts
            maxPixels: 1e9
        });

        return {
            'count': imageCount,
            'image': image,
            'water_area': waterArea.get('VV'), // Area in square meters
            'no_pixels': false
        };
    };

    // 3. Calculation
    const result1 = getWaterExtent(date1, regionOfInterest);
    const result2 = getWaterExtent(date2, regionOfInterest);

    // 4. Validation & Final Answer
    console.log(`Image count for ${date1}: ${result1.count}`);
    console.log(`Image count for ${date2}: ${result2.count}`);

    if (result1.count === 0 || result2.count === 0) {
        console.log(`No images found for one or both dates.`);
        console.log("A: Yes");
        return;
    }

    if (result1.no_pixels || result2.no_pixels) {
        console.log("No valid pixels in the ROI after mosaicking/clipping.");
        console.log("B: No");
        return;
    }

    const waterArea1_m2 = result1.water_area.getInfo();
    const waterArea2_m2 = result2.water_area.getInfo();

    if (waterArea1_m2 === null || waterArea2_m2 === null) {
        console.log("Calculation failed: could not retrieve water area for one or both dates.");
        console.log("C3: Calculation Failure");
        return;
    }

    // Convert area from m^2 to km^2 for readability
    const waterArea1_km2 = waterArea1_m2 / 1e6;
    const waterArea2_km2 = waterArea2_m2 / 1e6;

    console.log(`Surface water extent on ${date1}: ${waterArea1_km2.toFixed(2)} sq km`);
    console.log(`Surface water extent on ${date2}: ${waterArea2_km2.toFixed(2)} sq km`);

    if (waterArea2_km2 > waterArea1_km2) {
        console.log("Conclusion: Water extent increased.");
        console.log("A: Yes");
    } else {
        console.log("Conclusion: Water extent did not increase.");
        console.log("B: No");
    }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
    console.error(`Error: ${e}`);
    console.log("D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.");
});
